-- P10 franchise CRM and independent performance control (MAT-FUNC-036/037/038/046).
create table public.franchise_crm_prospects(
 id uuid primary key default extensions.gen_random_uuid(),franchise_id uuid not null references public.franchises(id)on delete restrict,territory_version_id uuid not null,prospect_type text not null check(prospect_type in('CLIENT','PROVIDER')),display_name text not null check(length(btrim(display_name))between 2 and 200),contact_email extensions.citext not null,organization_name text,source_code text not null check(source_code~'^[A-Z][A-Z0-9_]{2,63}$'),pipeline_stage text not null default'SENT'check(pipeline_stage in('SENT','OPENED','REGISTERED','PROFILE_STARTED','VERIFIED','DIAGNOSTIC_STARTED','OPPORTUNITY_CREATED','RFQ_STARTED','CONTRACT_SIGNED')),next_followup_at timestamptz,owner_user_id uuid not null references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),row_version integer not null default 1 check(row_version>0),foreign key(territory_version_id,franchise_id)references public.franchise_territory_versions(id,franchise_id)on delete restrict,unique(franchise_id,contact_email,prospect_type)
);
create table public.franchise_crm_activities(
 id bigint generated always as identity primary key,franchise_id uuid not null references public.franchises(id)on delete restrict,prospect_id uuid not null references public.franchise_crm_prospects(id)on delete restrict,activity_type text not null check(activity_type in('CALL','EMAIL','MEETING','NOTE','FOLLOW_UP','INVITATION')),occurred_at timestamptz not null,summary text not null check(length(btrim(summary))between 3 and 2000),evidence_refs jsonb not null default'[]'check(jsonb_typeof(evidence_refs)='array'),next_followup_at timestamptz,actor_user_id uuid not null references auth.users(id),correlation_id uuid not null,created_at timestamptz not null default clock_timestamp()
);
create table public.franchise_pipeline_events(
 id bigint generated always as identity primary key,franchise_id uuid not null references public.franchises(id)on delete restrict,prospect_id uuid not null references public.franchise_crm_prospects(id)on delete restrict,from_stage text,to_stage text not null,reason_code text not null check(length(btrim(reason_code))between 3 and 80),evidence_refs jsonb not null check(jsonb_typeof(evidence_refs)='array'),idempotency_key text not null,actor_user_id uuid not null references auth.users(id),correlation_id uuid not null,occurred_at timestamptz not null default clock_timestamp(),unique(prospect_id,idempotency_key)
);
create table public.franchise_performance_metric_versions(
 id uuid primary key default extensions.gen_random_uuid(),metric_code text not null check(metric_code~'^[A-Z][A-Z0-9_]{2,79}$'),version integer not null check(version>0),axis_code text not null check(axis_code in('CLIENT_NETWORK','LIBRARY_QUALITY','PROVIDER_NETWORK','DELIVERY_PERFORMANCE','CLIENT_SATISFACTION','COMPLIANCE_FINANCE')),label_fr text not null,label_ar text not null,weight_basis_points integer not null check(weight_basis_points between 0 and 10000),warning_below_basis_points integer not null check(warning_below_basis_points between 0 and 10000),status text not null check(status in('DRAFT','ACTIVE','RETIRED')),source_contract jsonb not null check(jsonb_typeof(source_contract)='object'),effective_from timestamptz not null,effective_until timestamptz,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(metric_code,version),unique(id,metric_code),check(effective_until is null or effective_until>effective_from)
);
create unique index franchise_performance_metric_active_uidx on public.franchise_performance_metric_versions(metric_code)where status='ACTIVE';
create table public.franchise_performance_score_snapshots(
 id uuid primary key default extensions.gen_random_uuid(),franchise_id uuid not null references public.franchises(id)on delete restrict,period_start date not null,period_end date not null,model_version text not null check(length(btrim(model_version))between 1 and 80),global_score_basis_points integer not null check(global_score_basis_points between 0 and 10000),library_quality_score_basis_points integer not null check(library_quality_score_basis_points between 0 and 10000),axis_scores jsonb not null check(jsonb_typeof(axis_scores)='object'),measurements_snapshot jsonb not null check(jsonb_typeof(measurements_snapshot)='array'),source_evidence_hash text not null check(source_evidence_hash~'^[0-9a-f]{64}$'),health_suggestion text not null check(health_suggestion in('HEALTHY','ATTENTION','IMPROVEMENT_PLAN','UNDER_REVIEW')),previous_snapshot_id uuid references public.franchise_performance_score_snapshots(id)on delete restrict,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(franchise_id,period_start,period_end,model_version),check(period_end>=period_start)
);
create table public.franchise_performance_alerts(
 id uuid primary key default extensions.gen_random_uuid(),franchise_id uuid not null references public.franchises(id)on delete restrict,snapshot_id uuid not null references public.franchise_performance_score_snapshots(id)on delete restrict,alert_type text not null check(alert_type in('KPI_THRESHOLD','LIBRARY_QUALITY','SLA','FAVORITISM_RISK','COMPLIANCE','FINANCE')),severity text not null check(severity in('INFO','WARNING','CRITICAL')),status text not null default'OPEN'check(status in('OPEN','ACKNOWLEDGED','RESOLVED')),metric_code text,explanation_fr text not null,explanation_ar text not null,evidence_refs jsonb not null check(jsonb_typeof(evidence_refs)='array'),rule_version text not null,created_at timestamptz not null default clock_timestamp(),resolved_at timestamptz,check((status='RESOLVED')=(resolved_at is not null))
);
create table public.franchise_performance_objective_versions(
 id uuid primary key default extensions.gen_random_uuid(),franchise_id uuid not null references public.franchises(id)on delete restrict,objective_code text not null check(objective_code~'^[A-Z][A-Z0-9_]{2,79}$'),version integer not null check(version>0),title_fr text not null,title_ar text not null,target_value bigint not null check(target_value>=0),current_value bigint not null check(current_value>=0),unit_code text not null,status text not null check(status in('ACTIVE','ACHIEVED','CANCELLED')),owner_user_id uuid not null references auth.users(id),starts_on date not null,due_on date not null,rule_version text not null,evidence_refs jsonb not null check(jsonb_typeof(evidence_refs)='array'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(franchise_id,objective_code,version),check(due_on>=starts_on)
);

create function private.franchise_crm_write_access(p_franchise uuid,p_actor uuid default auth.uid())returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$select exists(select 1 from public.franchises f where f.id=p_franchise and private.has_org_role(f.operator_organization_id,array['FRANCHISE_OWNER','FRANCHISE_MANAGER'],p_actor))or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],p_actor)$$;

create function public.save_franchise_prospect(p_franchise_id uuid,p_prospect_id uuid,p_territory_version_id uuid,p_prospect_type text,p_display_name text,p_contact_email text,p_organization_name text,p_source_code text,p_next_followup_at timestamptz,p_owner_user_id uuid,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();x public.franchise_crm_prospects%rowtype;h text;r jsonb;pid uuid;newv integer;begin if a is null or not private.franchise_crm_write_access(p_franchise_id,a)then raise exception'FRANCHISE_CRM_WRITE_DENIED'using errcode='42501';end if;if p_prospect_type not in('CLIENT','PROVIDER')or length(btrim(coalesce(p_display_name,'')))not between 2 and 200 or p_contact_email!~*'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'or p_source_code!~'^[A-Z][A-Z0-9_]{2,63}$'or not exists(select 1 from public.franchise_territory_versions t where t.id=p_territory_version_id and t.franchise_id=p_franchise_id)then raise exception'INVALID_FRANCHISE_PROSPECT'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('franchise',p_franchise_id,'prospect',p_prospect_id,'territory',p_territory_version_id,'type',p_prospect_type,'name',p_display_name,'email',lower(p_contact_email),'organization',p_organization_name,'source',p_source_code,'followup',p_next_followup_at,'owner',p_owner_user_id,'expected',p_expected_row_version));r:=private.begin_contract_command((select operator_organization_id from public.franchises where id=p_franchise_id),'franchise.crm.prospect.save',p_idempotency_key,h,a);if r is not null then return r;end if;if p_prospect_id is null then if p_expected_row_version<>0 then raise exception'STALE_FRANCHISE_PROSPECT'using errcode='40001';end if;insert into public.franchise_crm_prospects(franchise_id,territory_version_id,prospect_type,display_name,contact_email,organization_name,source_code,next_followup_at,owner_user_id,created_by)values(p_franchise_id,p_territory_version_id,p_prospect_type,p_display_name,p_contact_email,p_organization_name,p_source_code,p_next_followup_at,p_owner_user_id,a)returning id,row_version into pid,newv;else update public.franchise_crm_prospects set display_name=p_display_name,organization_name=p_organization_name,next_followup_at=p_next_followup_at,owner_user_id=p_owner_user_id,updated_at=clock_timestamp(),row_version=row_version+1 where id=p_prospect_id and franchise_id=p_franchise_id and row_version=p_expected_row_version returning id,row_version into pid,newv;if not found then raise exception'STALE_FRANCHISE_PROSPECT'using errcode='40001';end if;end if;r:=jsonb_build_object('outcome','FRANCHISE_PROSPECT_SAVED','prospect_id',pid,'row_version',newv);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)select f.operator_organization_id,a,'USER','franchise.crm.prospect_saved','franchise_prospect',pid::text,p_correlation_id,jsonb_build_object('franchise_id',f.id,'prospect_type',p_prospect_type),repeat('0',64)from public.franchises f where f.id=p_franchise_id;insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)select f.operator_organization_id,'franchise_prospect',pid::text,'FranchiseProspectSavedV1',p_correlation_id,r,p_idempotency_key from public.franchises f where f.id=p_franchise_id;perform private.finish_contract_command((select operator_organization_id from public.franchises where id=p_franchise_id),'franchise.crm.prospect.save',p_idempotency_key,r);return r;end$$;

create function public.record_franchise_activity(p_prospect_id uuid,p_activity_type text,p_occurred_at timestamptz,p_summary text,p_evidence_refs jsonb,p_next_followup_at timestamptz,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();p public.franchise_crm_prospects%rowtype;h text;r jsonb;aid bigint;org uuid;begin select*into p from public.franchise_crm_prospects where id=p_prospect_id for update;if a is null or not found or not private.franchise_crm_write_access(p.franchise_id,a)then raise exception'FRANCHISE_ACTIVITY_DENIED'using errcode='42501';end if;if p_activity_type not in('CALL','EMAIL','MEETING','NOTE','FOLLOW_UP','INVITATION')or length(btrim(coalesce(p_summary,'')))not between 3 and 2000 or jsonb_typeof(p_evidence_refs)<>'array'then raise exception'INVALID_FRANCHISE_ACTIVITY'using errcode='22023';end if;select operator_organization_id into org from public.franchises where id=p.franchise_id;h:=private.canonical_request_hash(jsonb_build_object('prospect',p.id,'type',p_activity_type,'occurred',p_occurred_at,'summary',p_summary,'evidence',p_evidence_refs,'followup',p_next_followup_at));r:=private.begin_contract_command(org,'franchise.crm.activity.record',p_idempotency_key,h,a);if r is not null then return r;end if;insert into public.franchise_crm_activities(franchise_id,prospect_id,activity_type,occurred_at,summary,evidence_refs,next_followup_at,actor_user_id,correlation_id)values(p.franchise_id,p.id,p_activity_type,p_occurred_at,p_summary,p_evidence_refs,p_next_followup_at,a,p_correlation_id)returning id into aid;update public.franchise_crm_prospects set next_followup_at=p_next_followup_at,updated_at=clock_timestamp(),row_version=row_version+1 where id=p.id;r:=jsonb_build_object('outcome','FRANCHISE_ACTIVITY_RECORDED','activity_id',aid,'prospect_id',p.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(org,a,'USER','franchise.crm.activity_recorded','franchise_activity',aid::text,p_correlation_id,jsonb_build_object('franchise_id',p.franchise_id,'prospect_id',p.id,'activity_type',p_activity_type),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(org,'franchise_prospect',p.id::text,'FranchiseActivityRecordedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(org,'franchise.crm.activity.record',p_idempotency_key,r);return r;end$$;

create function public.advance_franchise_pipeline(p_prospect_id uuid,p_to_stage text,p_reason_code text,p_evidence_refs jsonb,p_expected_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();p public.franchise_crm_prospects%rowtype;stages text[]:=array['SENT','OPENED','REGISTERED','PROFILE_STARTED','VERIFIED','DIAGNOSTIC_STARTED','OPPORTUNITY_CREATED','RFQ_STARTED','CONTRACT_SIGNED'];h text;r jsonb;org uuid;begin select*into p from public.franchise_crm_prospects where id=p_prospect_id for update;if a is null or not found or not private.franchise_crm_write_access(p.franchise_id,a)then raise exception'FRANCHISE_PIPELINE_DENIED'using errcode='42501';end if;if array_position(stages,p_to_stage)<>array_position(stages,p.pipeline_stage)+1 or length(btrim(coalesce(p_reason_code,'')))not between 3 and 80 or jsonb_typeof(p_evidence_refs)<>'array'then raise exception'INVALID_PIPELINE_TRANSITION'using errcode='23514';end if;select operator_organization_id into org from public.franchises where id=p.franchise_id;h:=private.canonical_request_hash(jsonb_build_object('prospect',p.id,'from',p.pipeline_stage,'to',p_to_stage,'reason',p_reason_code,'evidence',p_evidence_refs,'expected',p_expected_row_version));r:=private.begin_contract_command(org,'franchise.crm.pipeline.advance.'||p.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;if p.row_version<>p_expected_row_version then raise exception'STALE_FRANCHISE_PROSPECT'using errcode='40001';end if;update public.franchise_crm_prospects set pipeline_stage=p_to_stage,updated_at=clock_timestamp(),row_version=row_version+1 where id=p.id;insert into public.franchise_pipeline_events(franchise_id,prospect_id,from_stage,to_stage,reason_code,evidence_refs,idempotency_key,actor_user_id,correlation_id)values(p.franchise_id,p.id,p.pipeline_stage,p_to_stage,p_reason_code,p_evidence_refs,p_idempotency_key,a,p_correlation_id);r:=jsonb_build_object('outcome','FRANCHISE_PIPELINE_ADVANCED','prospect_id',p.id,'from_stage',p.pipeline_stage,'to_stage',p_to_stage,'row_version',p.row_version+1);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(org,a,'USER','franchise.crm.pipeline_advanced','franchise_prospect',p.id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(org,'franchise_prospect',p.id::text,'FranchisePipelineAdvancedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(org,'franchise.crm.pipeline.advance.'||p.id::text,p_idempotency_key,r);return r;end$$;

create function public.record_franchise_performance_snapshot(p_franchise_id uuid,p_period_start date,p_period_end date,p_model_version text,p_measurements jsonb,p_source_evidence_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$declare a uuid:=auth.uid();org uuid;h text;r jsonb;sid uuid;global_score integer;library_score integer;axis jsonb;health text;previous uuid;begin if a is null or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN'],a)then raise exception'FRANCHISE_PERFORMANCE_RECORD_DENIED'using errcode='42501';end if;if p_period_end<p_period_start or length(btrim(coalesce(p_model_version,'')))not between 1 and 80 or p_source_evidence_hash!~'^[0-9a-f]{64}$'or jsonb_typeof(p_measurements)<>'array'or jsonb_array_length(p_measurements)=0 or exists(select 1 from jsonb_array_elements(p_measurements)m where coalesce((m->>'numerator')::bigint,-1)<0 or coalesce((m->>'denominator')::bigint,0)<=0 or not exists(select 1 from public.franchise_performance_metric_versions v where v.id=(m->>'metric_version_id')::uuid and v.status='ACTIVE'and v.effective_from<=p_period_end::timestamptz and(v.effective_until is null or v.effective_until>p_period_end::timestamptz)))then raise exception'INVALID_PERFORMANCE_MEASUREMENTS'using errcode='22023';end if;select operator_organization_id into org from public.franchises where id=p_franchise_id;if org is null then raise exception'FRANCHISE_NOT_FOUND'using errcode='P0002';end if;h:=private.canonical_request_hash(jsonb_build_object('franchise',p_franchise_id,'start',p_period_start,'end',p_period_end,'model',p_model_version,'measurements',p_measurements,'evidence_hash',p_source_evidence_hash));r:=private.begin_contract_command(org,'franchise.performance.snapshot',p_idempotency_key,h,a);if r is not null then return r;end if;with valueset as(select v.axis_code,v.metric_code,v.weight_basis_points,least(10000,((m->>'numerator')::numeric*10000/(m->>'denominator')::numeric))::integer score from jsonb_array_elements(p_measurements)m join public.franchise_performance_metric_versions v on v.id=(m->>'metric_version_id')::uuid),axes as(select axis_code,(sum(score::bigint*weight_basis_points)/nullif(sum(weight_basis_points),0))::integer score from valueset group by axis_code)select coalesce((select(sum(score::bigint*weight_basis_points)/nullif(sum(weight_basis_points),0))::integer from valueset),0),coalesce((select score from axes where axis_code='LIBRARY_QUALITY'),0),coalesce((select jsonb_object_agg(axis_code,score)from axes),'{}')into global_score,library_score,axis;health:=case when global_score>=8000 then'HEALTHY'when global_score>=6000 then'ATTENTION'when global_score>=4000 then'IMPROVEMENT_PLAN'else'UNDER_REVIEW'end;select id into previous from public.franchise_performance_score_snapshots where franchise_id=p_franchise_id order by period_end desc,created_at desc limit 1;insert into public.franchise_performance_score_snapshots(franchise_id,period_start,period_end,model_version,global_score_basis_points,library_quality_score_basis_points,axis_scores,measurements_snapshot,source_evidence_hash,health_suggestion,previous_snapshot_id,created_by)values(p_franchise_id,p_period_start,p_period_end,p_model_version,global_score,library_score,axis,p_measurements,p_source_evidence_hash,health,previous,a)returning id into sid;insert into public.franchise_performance_alerts(franchise_id,snapshot_id,alert_type,severity,metric_code,explanation_fr,explanation_ar,evidence_refs,rule_version)select p_franchise_id,sid,case when v.axis_code='LIBRARY_QUALITY'then'LIBRARY_QUALITY'else'KPI_THRESHOLD'end,case when q.score<4000 then'CRITICAL'else'WARNING'end,v.metric_code,'Indicateur sous le seuil versionné','مؤشر دون الحد المعتمد',coalesce(m->'evidence_refs','[]'),p_model_version from jsonb_array_elements(p_measurements)m join public.franchise_performance_metric_versions v on v.id=(m->>'metric_version_id')::uuid cross join lateral(select least(10000,((m->>'numerator')::numeric*10000/(m->>'denominator')::numeric))::integer score)q where q.score<v.warning_below_basis_points;r:=jsonb_build_object('outcome','FRANCHISE_PERFORMANCE_SNAPSHOTTED','snapshot_id',sid,'global_score_basis_points',global_score,'library_quality_score_basis_points',library_score,'health_suggestion',health);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(org,a,'USER','franchise.performance.snapshotted','franchise_performance_snapshot',sid::text,p_correlation_id,jsonb_build_object('franchise_id',p_franchise_id,'model_version',p_model_version,'score_basis_points',global_score,'human_review_required',health<>'HEALTHY'),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(org,'franchise_performance',p_franchise_id::text,'FranchisePerformanceSnapshottedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(org,'franchise.performance.snapshot',p_idempotency_key,r);return r;end$$;

do $$declare t text;begin foreach t in array array['franchise_crm_prospects','franchise_crm_activities','franchise_pipeline_events','franchise_performance_metric_versions','franchise_performance_score_snapshots','franchise_performance_alerts','franchise_performance_objective_versions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create policy franchise_prospects_scoped_read on public.franchise_crm_prospects for select to authenticated using(private.franchise_access(franchise_id));create policy franchise_activities_scoped_read on public.franchise_crm_activities for select to authenticated using(private.franchise_access(franchise_id));create policy franchise_pipeline_scoped_read on public.franchise_pipeline_events for select to authenticated using(private.franchise_access(franchise_id));create policy franchise_metrics_active_read on public.franchise_performance_metric_versions for select to authenticated using(status='ACTIVE'or private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','READ_ONLY_AUDITOR']));create policy franchise_scores_scoped_read on public.franchise_performance_score_snapshots for select to authenticated using(private.franchise_access(franchise_id));create policy franchise_alerts_scoped_read on public.franchise_performance_alerts for select to authenticated using(private.franchise_access(franchise_id));create policy franchise_objectives_scoped_read on public.franchise_performance_objective_versions for select to authenticated using(private.franchise_access(franchise_id));
grant select on public.franchise_crm_prospects,public.franchise_crm_activities,public.franchise_pipeline_events,public.franchise_performance_metric_versions,public.franchise_performance_score_snapshots,public.franchise_performance_alerts,public.franchise_performance_objective_versions to authenticated;
create trigger franchise_crm_activities_immutable before update or delete on public.franchise_crm_activities for each row execute function private.prevent_franchise_history_change();create trigger franchise_pipeline_events_immutable before update or delete on public.franchise_pipeline_events for each row execute function private.prevent_franchise_history_change();create trigger franchise_performance_metrics_immutable before update or delete on public.franchise_performance_metric_versions for each row execute function private.prevent_franchise_history_change();create trigger franchise_performance_scores_immutable before update or delete on public.franchise_performance_score_snapshots for each row execute function private.prevent_franchise_history_change();create trigger franchise_performance_objectives_immutable before update or delete on public.franchise_performance_objective_versions for each row execute function private.prevent_franchise_history_change();
revoke all on function private.franchise_crm_write_access(uuid,uuid)from public,anon,authenticated,service_role;grant execute on function private.franchise_crm_write_access(uuid,uuid)to authenticated;
revoke all on function public.save_franchise_prospect(uuid,uuid,uuid,text,text,text,text,text,timestamptz,uuid,integer,text,uuid),public.record_franchise_activity(uuid,text,timestamptz,text,jsonb,timestamptz,text,uuid),public.advance_franchise_pipeline(uuid,text,text,jsonb,integer,text,uuid),public.record_franchise_performance_snapshot(uuid,date,date,text,jsonb,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.save_franchise_prospect(uuid,uuid,uuid,text,text,text,text,text,timestamptz,uuid,integer,text,uuid),public.record_franchise_activity(uuid,text,timestamptz,text,jsonb,timestamptz,text,uuid),public.advance_franchise_pipeline(uuid,text,text,jsonb,integer,text,uuid),public.record_franchise_performance_snapshot(uuid,date,date,text,jsonb,text,text,uuid)to authenticated;
create index franchise_prospects_pipeline_idx on public.franchise_crm_prospects(franchise_id,pipeline_stage,next_followup_at);create index franchise_activities_timeline_idx on public.franchise_crm_activities(franchise_id,prospect_id,occurred_at desc,id desc);create index franchise_pipeline_timeline_idx on public.franchise_pipeline_events(franchise_id,prospect_id,occurred_at desc,id desc);create index franchise_scores_period_idx on public.franchise_performance_score_snapshots(franchise_id,period_end desc,created_at desc);create index franchise_alerts_open_idx on public.franchise_performance_alerts(franchise_id,severity,created_at desc)where status='OPEN';create index franchise_objectives_active_idx on public.franchise_performance_objective_versions(franchise_id,due_on)where status='ACTIVE';
notify pgrst,'reload schema';
